const raw = $input.first().json;
const body = raw.body ?? raw;

const taskTitle = body.taskTitle || 'Adsız Proje';
const taskDescription = body.taskDescription || '';
const userId = body.userId || null;
const supabaseToken = body.supabaseToken || null;

const profile = body.userProfile || {};
const focusPeriod = profile.focusPeriod ?? 25;
const energyPeak = profile.energyPeak ?? 'morning';
const workHours = profile.workHours ?? { start: '09:00', end: '18:00' };
const mainObstacle = profile.mainObstacle ?? 'paralysis';
const breakStyle = profile.breakStyle ?? 'long-break';

const deadlineRaw = body.deadline || body.targetDate;
if (!deadlineRaw) {
  throw new Error("Webhook payload'inda deadline veya targetDate olmali");
}

const now = new Date();
let deadline = new Date(deadlineRaw);
if (!body.deadline && body.targetDate) {
  deadline.setHours(23, 59, 0, 0);
}

const msPerDay = 24 * 60 * 60 * 1000;
const availableDays = Math.max(1, Math.ceil((deadline.getTime() - now.getTime()) / msPerDay));

// Gunluk kapasite: calisma saatlerine kac odak seansi sigar
function toMin(hhmm) { const p = String(hhmm).split(':').map(Number); return (p[0] || 0) * 60 + (p[1] || 0); }
const breakMap = { pomodoro: 5, 'long-break': 15, micro: 2, free: 0 };
const breakMinutes = breakMap[breakStyle] != null ? breakMap[breakStyle] : 15;
const slotsPerDay = Math.max(1, Math.floor((toMin(workHours.end) - toMin(workHours.start)) / (focusPeriod + breakMinutes)));
const perDayCap = Math.min(slotsPerDay, 3); // DEHB: gunde en fazla ~3 odak seansi

// Gorev sayisi araligi — AI karmasikliga gore bu aralikta secer
const minTasks = Math.max(3, Math.ceil(availableDays / 2));
const maxTasks = Math.max(minTasks + 1, availableDays * perDayCap);

return [{
  json: {
    taskTitle,
    taskDescription,
    userId,
    supabaseToken,
    now: now.toISOString(),
    deadline: deadline.toISOString(),
    availableDays,
    minTasks,
    maxTasks,
    profile: { focusPeriod, energyPeak, workHours, mainObstacle, breakStyle, breakMinutes }
  }
}];

