// ── FocusAid — Görev Dağıtımı (rapor algoritması) ──
// AI Agent sadece görev + cognitive_load üretir; planlamayı burada yaparız.
const merged = $('Merge').first().json;
const aiRaw = $json.output || '{"tasks":[]}';

let parsed;
try { parsed = JSON.parse(aiRaw); }
catch (e) { throw new Error('AI Agent gecerli JSON dondurmedi: ' + String(aiRaw).slice(0, 300)); }
const rawTasks = Array.isArray(parsed) ? parsed : (parsed.tasks || []);
if (rawTasks.length === 0) throw new Error('AI Agent hic gorev uretmedi');

const profile = merged.profile || {};
const workHours = profile.workHours || {};
const focusPeriod = profile.focusPeriod || 25;
const existingEvents = merged.existingEvents || [];

// Mola süresi (dk): profil breakStyle'a göre, yoksa 15 dk (rapor: en az 15 dk ara)
const breakMap = { pomodoro: 5, 'long-break': 15, micro: 2, free: 0 };
const breakMinutes = (profile.breakMinutes != null) ? Number(profile.breakMinutes)
  : (breakMap[profile.breakStyle] != null ? breakMap[profile.breakStyle] : 15);
const step = focusPeriod + breakMinutes;

function pad(n) { return String(n).padStart(2, '0'); }
function toMin(hhmm) { const p = String(hhmm).split(':').map(Number); return (p[0] || 0) * 60 + (p[1] || 0); }
const workStartMin = toMin(workHours.start || '09:00');
const workEndMin = toMin(workHours.end || '18:00');

// Istanbul (UTC+3) duvar saati — sunucu timezone'undan bağımsız
const IST = 3 * 3600 * 1000;
function wall(iso) { return new Date(new Date(iso).getTime() + IST); } // getUTC* ile oku
function keyOf(w) { return w.getUTCFullYear() + '-' + pad(w.getUTCMonth() + 1) + '-' + pad(w.getUTCDate()); }
function minsOf(w) { return w.getUTCHours() * 60 + w.getUTCMinutes(); }

// 1) scheduledSlots — mevcut takvim etkinliklerinden dolu aralıklar (gün bazında)
const occ = {};
function reserve(key, a, b) { (occ[key] = occ[key] || []).push({ a, b }); }
function isFree(key, a, b) { return !(occ[key] || []).some(o => a < o.b && b > o.a); }
for (const ev of existingEvents) {
  const s = ev.start && (ev.start.dateTime || ev.start.date);
  const e = ev.end && (ev.end.dateTime || ev.end.date);
  if (!s || !e) continue;
  const sw = wall(s), ew = wall(e);
  reserve(keyOf(sw), minsOf(sw), minsOf(ew));
}

// 2) availableDays — BUGUNDEN deadline'a, en az 1 bos slotu olan gunler
// Bugun icin gecmis saatlere gorev koymamak adina 'simdi + tampon'dan baslanir.
const nowW = wall(merged.now || new Date().toISOString());
const deadW = wall(merged.deadline || merged.now);
const deadlineMin = minsOf(deadW);
const todayKey = keyOf(nowW);
const nowMin   = minsOf(nowW);
const LEAD_MIN = 15; // gorev en erken 15 dk sonra baslasin
function startMinFor(key) {
  return key === todayKey ? Math.max(workStartMin, nowMin + LEAD_MIN) : workStartMin;
}
let cur = new Date(Date.UTC(nowW.getUTCFullYear(), nowW.getUTCMonth(), nowW.getUTCDate()));
const lastAnchor = Date.UTC(deadW.getUTCFullYear(), deadW.getUTCMonth(), deadW.getUTCDate());
const days = [];
while (cur.getTime() <= lastAnchor) {
  const key = cur.getUTCFullYear() + '-' + pad(cur.getUTCMonth() + 1) + '-' + pad(cur.getUTCDate());
  const endMin = (cur.getTime() === lastAnchor) ? Math.min(workEndMin, deadlineMin) : workEndMin;
  let free = false;
  for (let m = startMinFor(key); m + focusPeriod <= endMin; m += step) { if (isFree(key, m, m + focusPeriod)) { free = true; break; } }
  if (free) days.push({ key, endMin });
  cur = new Date(cur.getTime() + 24 * 3600 * 1000);
}
if (days.length === 0) {
  const d = new Date(Date.UTC(nowW.getUTCFullYear(), nowW.getUTCMonth(), nowW.getUTCDate() + 1));
  days.push({ key: d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate()), endMin: workEndMin });
}

// 3) maxPerDay + proportional dağıtım
const T = rawTasks.length;
const A = days.length;
const maxPerDay = Math.ceil(T / A);
const count = {};
function findSlot(day) {
  if ((count[day.key] || 0) >= maxPerDay) return null;
  for (let m = startMinFor(day.key); m + focusPeriod <= day.endMin; m += step) {
    if (isFree(day.key, m, m + focusPeriod)) return m;
  }
  return null;
}

const results = [];
for (let i = 0; i < T; i++) {
  const t = rawTasks[i] || {};
  const targetIdx = A > 1 ? Math.round(i * (A - 1) / (T - 1)) : 0;

  let day = null, startMin = null;
  let s = findSlot(days[targetIdx]);
  if (s !== null) { day = days[targetIdx]; startMin = s; }
  for (let j = targetIdx + 1; day === null && j < A; j++) { const x = findSlot(days[j]); if (x !== null) { day = days[j]; startMin = x; } }
  for (let j = targetIdx - 1; day === null && j >= 0; j--) { const x = findSlot(days[j]); if (x !== null) { day = days[j]; startMin = x; } }
  if (day === null) { day = days[A - 1]; startMin = startMinFor(day.key); } // taşma: son güne zorla

  reserve(day.key, startMin, startMin + focusPeriod);
  count[day.key] = (count[day.key] || 0) + 1;

  const endMinT = startMin + focusPeriod;
  const startISO = day.key + 'T' + pad(Math.floor(startMin / 60)) + ':' + pad(startMin % 60) + ':00+03:00';
  const endISO = day.key + 'T' + pad(Math.floor(endMinT / 60)) + ':' + pad(endMinT % 60) + ':00+03:00';

  results.push({
    json: {
      title: t.title || t.name || ('Gorev ' + (i + 1)),
      summary: t.summary || '',
      cognitiveLoad: t.cognitiveLoad || t.cognitive_load || 'medium',
      day: day.key,
      start: startISO,
      end: endISO,
      userId: merged.userId,
      supabaseToken: merged.supabaseToken,
      projectTitle: merged.taskTitle
    }
  });
}

return results;

// Her takvim etkinligi icin bir Supabase satiri uret.
// ONCEKI HATA: runOnceForAllItems modunda tek nesne donduruluyordu; N gorev
// parcalansa da Supabase'e yalnizca 1 kayit gidiyordu.
const events = $input.all();
const tasks  = $('Code in JavaScript').all();

return events.map((item, i) => {
  const task  = (tasks[i] || tasks[0]).json;
  const event = item.json;
  return {
    json: {
      user_id:           task.userId,
      project_title:     task.projectTitle,
      name:              task.title,
      summary:           task.summary,
      cognitive_load:    task.cognitiveLoad,
      day:               task.day,
      start_time:        task.start,
      end_time:          task.end,
      calendar_event_id: event.id,
      completed:         false
    }
  };
});
